(1304331, 163627, 3569, '<td valign="top">beautiful shot of a common subject.</td>', 'beautiful shot of a common subject.', '2005-04-19 14:23:06.000000', NULL, 1),
(1304332, 162733, 8522, '<td valign="top">Composition doesn''t convince me. Usually the eyes work best when used with rule of thirds, and negative space usually works in the direction an animal is facing. Composition and cropping seem like an afterthought here.</td>', 'Composition doesn''t convince me. Usually the eyes work best when used with rule of thirds, and negative space usually works in the direction an animal is facing. Composition and cropping seem like an afterthought here.', '2005-04-19 14:23:08.000000', NULL, 1),
(1304334, 168292, 22689, '<td valign="top">Lovely effect !</td>', 'Lovely effect !', '2005-04-19 14:23:56.000000', NULL, 1),
