(1305411, 167885, 33947, '<td valign="top">Very appealing compositon because of the beautiful light.</td>', 'Very appealing compositon because of the beautiful light.', '2005-04-19 19:50:23.000000', NULL, 1),
(1305412, 167337, 14476, '<td valign="top">excellent subject matter and composition.  great color too. what''s not to like!</td>', 'excellent subject matter and composition.  great color too. what''s not to like!', '2005-04-19 19:50:29.000000', NULL, 1),
