(1323437, 167271, 13879, '<td valign="top">Drops are stunning. Shame the tap/pipe is slightly out of focus</td>', 'Drops are stunning. Shame the tap/pipe is slightly out of focus', '2005-04-25 11:13:20.000000', NULL, 1),
(1323441, 164527, 4517, '<td valign="top">Blimey, how many kites :)</td>', 'Blimey, how many kites :)', '2005-04-25 11:13:32.000000', NULL, 1),
