(1324173, 167305, 22046, '<td valign="top">Like the sheen of light on the water and the one boat going by. Good lighting.</td>', 'Like the sheen of light on the water and the one boat going by. Good lighting.', '2005-04-25 14:23:45.000000', NULL, 1),
(1324177, 161722, 16520, '<td valign="top">Can''t tell if these are out in the wild in a zoo awesome capture any how..</td>', 'Can''t tell if these are out in the wild in a zoo awesome capture any how..', '2005-04-25 14:24:55.000000', NULL, 1),
(1324178, 165638, 33256, '<td valign="top">Nice exposure. Did you try any with the sun not so centered in the frame?</td>', 'Nice exposure. Did you try any with the sun not so centered in the frame?', '2005-04-25 14:24:57.000000', NULL, 1),
