(1325071, 164431, 32221, '<td valign="top">Perhaps a slightly tighter crop might work better?</td>', 'Perhaps a slightly tighter crop might work better?', '2005-04-25 17:46:51.000000', NULL, 1),
(1325072, 168295, 22734, '<td valign="top">What a sweetie pie, that patch between the eyes and ending at the tip of the nose adds extra interest to help bring out the lovely eyes.</td>', 'What a sweetie pie, that patch between the eyes and ending at the tip of the nose adds extra interest to help bring out the lovely eyes.', '2005-04-25 17:46:59.000000', NULL, 1),
(1325073, 161463, 25742, '<td valign="top">the green dildos are a big distraction. just the white against blue is enough.</td>', 'the green dildos are a big distraction. just the white against blue is enough.', '2005-04-25 17:47:06.000000', NULL, 1),
(1325074, 161122, 6532, '<td valign="top">Colors are brilliant - but, seem to be a bit overblown, especially noticeable in the yellows, oranges, and red.  The red spots in the land form are a bit distracting.</td>', 'Colors are brilliant - but, seem to be a bit overblown, especially noticeable in the yellows, oranges, and red.  The red spots in the land form are a bit distracting.', '2005-04-25 17:47:12.000000', NULL, 1),
