INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1326076, 167108, 23394, '<td valign="top">i''m not quite sure what happened here, but this really seems over-processed.  it has a very unnatural feel to it.  i could accept it as intentional if the subject matter was a bit more griping, but, as it is, i''m kinda lost.  hope this does well for you.  good luck!</td>', 'i''m not quite sure what happened here, but this really seems over-processed.  it has a very unnatural feel to it.  i could accept it as intentional if the subject matter was a bit more griping, but, as it is, i''m kinda lost.  hope this does well for you.  good luck!', '2005-04-25 22:08:29.000000', NULL, 1),
(1326081, 168277, 23394, '<td valign="top">i don''t even want to hazard a guess.  but, in any event, this will be one of my 10s for the challenge.  hope this does well for you.  good luck!</td>', 'i don''t even want to hazard a guess.  but, in any event, this will be one of my 10s for the challenge.  hope this does well for you.  good luck!', '2005-04-25 22:09:24.000000', NULL, 1),
(1326089, 168293, 23394, '<td valign="top">hahah!  that''s a riot.  and, well-executed (pardon the pun).  nice work, i''m sure the subject likes it as well.  hope this does well for you.  good luck!</td>', 'hahah!  that''s a riot.  and, well-executed (pardon the pun).  nice work, i''m sure the subject likes it as well.  hope this does well for you.  good luck!', '2005-04-25 22:11:09.000000', NULL, 1),
(1326094, 168251, 23394, '<td valign="top">rather desolate spot.  image probably would be more powerful if you could actually see a pile of bones down at the bottom ;-)<br/> <br/>very interesting treatment, especially with the water.  hope this does well for you.  good luck!</td>', 'rather desolate spot.  image probably would be more powerful if you could actually see a pile of bones down at the bottom ;-) very interesting treatment, especially with the water.  hope this does well for you.  good luck!', '2005-04-25 22:12:23.000000', NULL, 1),
(1326098, 167967, 23394, '<td valign="top">beautiful, serene image.  this is really a good example of when it''s ok to split the image with a horizon in the middle.  both the top and bottom halves are strong enough and interesting enough to stand on their own.  together, this rocks.  hope this does well for you.  good luck!</td>', 'beautiful, serene image.  this is really a good example of when it''s ok to split the image with a horizon in the middle.  both the top and bottom halves are strong enough and interesting enough to stand on their own.  together, this rocks.  hope this does well for you.  good luck!', '2005-04-25 22:13:59.000000', NULL, 1),
(1326100, 168120, 23394, '<td valign="top">rather interesting image you''ve captured.  lots of textures, lines, and drama in the skies.  title is weak, but won''t hold that against you.  hope this does well for you.  good luck!</td>', 'rather interesting image you''ve captured.  lots of textures, lines, and drama in the skies.  title is weak, but won''t hold that against you.  hope this does well for you.  good luck!', '2005-04-25 22:15:04.000000', NULL, 1),
